INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES ("ＴＰダウンカット", "boss_tp_down_cut", 4100610, "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", 10061005);
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES ("ＴＰ上昇ダウン", 3, 4100610, "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", 10061006);
